 "content": "from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            result.append((color, cells))
    return result

def _shape(cells):
    minr = min(r for r,c in cells)
    minc = min(c for r,c in cells)
    return frozenset((r-minr,c-minc) for r,c in cells)

def _variants(shape):
    pts = list(shape)
    variants = set()
    for reflect in (1, -1):
        for turns in range(4):
            transformed = []
            for r,c in pts:
                x, y = r, c * reflect
                for _ in range(turns):
                    x, y = y, -x
                transformed.append((x,y))
            mr = min(x for x,y in transformed)
            mc = min(y for x,y in transformed)
            variants.add(frozenset((x-mr,y-mc) for x,y in transformed))
    return variants

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    references = [(color, _shape(cells)) for color, cells in comps if color != 1]
    for color, cells in comps:
        if color != 1:
            continue
        shape = _shape(cells)
        choices = [refcolor for refcolor, refshape in references
                   if len(refshape) == len(shape) and refshape in _variants(shape)]
        if choices:
            new_color = choices[0]
            for r,c in cells:
                out[r][c] = new_color
    return out
